@import "@fontsource-variable/instrument-sans";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";

/* Light (faithful): white page, black ink, off-white paper for cards, a single form grey,
   hairline grey borders, stone grey behind white-on-media text. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0 0 0);
  --card: oklch(0.965 0.004 95);
  --card-foreground: oklch(0.366 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.366 0 0);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.928 0 0);
  --muted-foreground: oklch(0.366 0 0);
  --accent: oklch(0.96 0 0);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.56 0.19 28);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.81 0 0);
  --input: oklch(0.366 0 0);
  --ring: oklch(0 0 0);
  --highlight: oklch(0.72 0.012 85);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.46 0.012 85);
  --chart-1: oklch(0 0 0);
  --chart-2: oklch(0.366 0 0);
  --chart-3: oklch(0.6 0 0);
  --chart-4: oklch(0.81 0 0);
  --chart-5: oklch(0.46 0.012 85);
  --sidebar: oklch(0.965 0.004 95);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.928 0 0);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0.81 0 0);
  --sidebar-ring: oklch(0 0 0);

  --typeface-body: "Instrument Sans Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Instrument Sans Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  --radius: 0rem;
  --page-width: 100%;
  --page-gutter: 4.1vw;
  --section-y: 9vw;
}

@media (min-width: 40rem) {
  :root {
    --page-gutter: 1.3889vw;
    --section-y: 3.5vw;
  }
}

/* Dark (sibling): the roles swap: a near-black page with warm off-white ink, and the black
   bands become pale paper bands. Paper cards stay paper-toned but darker. */
.dark {
  --background: oklch(0.16 0 0);
  --foreground: oklch(0.96 0.004 95);
  --card: oklch(0.24 0.004 95);
  --card-foreground: oklch(0.86 0.004 95);
  --popover: oklch(0.2 0 0);
  --popover-foreground: oklch(0.96 0.004 95);
  --primary: oklch(0.96 0.004 95);
  --primary-foreground: oklch(0.16 0 0);
  --secondary: oklch(0.8 0.004 95);
  --secondary-foreground: oklch(0.16 0 0);
  --muted: oklch(0.27 0 0);
  --muted-foreground: oklch(0.78 0.004 95);
  --accent: oklch(0.24 0 0);
  --accent-foreground: oklch(0.96 0.004 95);
  --destructive: oklch(0.66 0.18 28);
  --destructive-foreground: oklch(0.16 0 0);
  --border: oklch(0.96 0.004 95 / 22%);
  --input: oklch(0.86 0.004 95);
  --ring: oklch(0.96 0.004 95);
  --highlight: oklch(0.58 0.012 85);
  --highlight-foreground: oklch(0.96 0.004 95);
  --glow: oklch(0.36 0.012 85);
  --chart-1: oklch(0.96 0.004 95);
  --chart-2: oklch(0.8 0.004 95);
  --chart-3: oklch(0.6 0 0);
  --chart-4: oklch(0.4 0 0);
  --chart-5: oklch(0.58 0.012 85);
  --sidebar: oklch(0.2 0 0);
  --sidebar-foreground: oklch(0.96 0.004 95);
  --sidebar-primary: oklch(0.96 0.004 95);
  --sidebar-primary-foreground: oklch(0.16 0 0);
  --sidebar-accent: oklch(0.27 0 0);
  --sidebar-accent-foreground: oklch(0.96 0.004 95);
  --sidebar-border: oklch(0.96 0.004 95 / 22%);
  --sidebar-ring: oklch(0.96 0.004 95);
}
